CREATE TABLE IF NOT EXISTS bank_transactions (source TEXT NOT NULL,account_id TEXT NOT NULL,external_id TEXT NOT NULL,occurred_at TEXT NOT NULL,amount_minor INTEGER NOT NULL,currency TEXT NOT NULL,description TEXT,raw_json TEXT NOT NULL,imported_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(source,account_id,external_id)); CREATE TABLE IF NOT EXISTS accounting_exports (provider TEXT NOT NULL,source TEXT NOT NULL,account_id TEXT NOT NULL,external_id TEXT NOT NULL,destination_company_id TEXT,destination_account_id TEXT,destination_type TEXT,destination_id TEXT,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','already_posted','ambiguous','error')),match_method TEXT,matched_at TEXT,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(provider,source,account_id,external_id),FOREIGN KEY(source,account_id,external_id) REFERENCES bank_transactions(source,account_id,external_id)); CREATE INDEX IF NOT EXISTS idx_accounting_exports_status ON accounting_exports(provider,status);